string widoczne(const string& s) {
    const char* hx = "0123456789abcdef";
    string r;
    for (unsigned char c : s) {
        if (c == '\n') r += "\\n";
        else if (c == '\r') r += "\\r";
        else if (c == '\t') r += "\\t";
        else if (c < 32 || c >= 127) { r += "\\x"; r += hx[c / 16]; r += hx[c % 16]; }
        else r += char(c);
    }
    return r;
}

