#include <bits/stdc++.h>
using namespace std;

// liczba znaków (code pointów) w napisie UTF-8
size_t dlugoscUtf8(const string& s) {
    size_t n = 0;
    for (unsigned char c : s)
        if ((c & 0xC0) != 0x80) n++;
    return n;
}

// UTF-8 -> UTF-32 (zakłada poprawne dane)
u32string dekoduj(const string& s) {
    u32string r;
    for (size_t i = 0; i < s.size();) {
        unsigned char c = s[i];
        int len = c < 0x80 ? 1 : c < 0xE0 ? 2 : c < 0xF0 ? 3 : 4;
        char32_t cp = len == 1 ? c : c & (0xFF >> (len + 1));
        for (int k = 1; k < len; k++) cp = (cp << 6) | ((unsigned char)s[i + k] & 0x3F);
        r += cp;
        i += len;
    }
    return r;
}

// UTF-32 -> UTF-8
string koduj(const u32string& u) {
    string r;
    for (char32_t cp : u) {
        if (cp < 0x80) r += char(cp);
        else if (cp < 0x800) { r += char(0xC0 | (cp >> 6)); r += char(0x80 | (cp & 0x3F)); }
        else if (cp < 0x10000) { r += char(0xE0 | (cp >> 12)); r += char(0x80 | ((cp >> 6) & 0x3F)); r += char(0x80 | (cp & 0x3F)); }
        else { r += char(0xF0 | (cp >> 18)); r += char(0x80 | ((cp >> 12) & 0x3F));
               r += char(0x80 | ((cp >> 6) & 0x3F)); r += char(0x80 | (cp & 0x3F)); }
    }
    return r;
}

int main() {
    string s = "żółw";
    cout << s.size() << ' ' << dlugoscUtf8(s) << '\n';   // 7 4
    u32string u = dekoduj(s);
    for (char32_t cp : u) cout << "U+" << hex << uppercase << (unsigned)cp << ' ';
    cout << dec << '\n';                                 // U+17C U+F3 U+142 U+77
    reverse(u.begin(), u.end());                         // odwracamy znaki, nie bajty
    cout << koduj(u) << '\n';                            // wółż
}

